// ❌ 데이터와 setter 같은 Context
const AppContext = React.createContext({
  user: null,
  setUser: () => {},
})
// user 바뀌면 setUser만 쓰는 컴포넌트도 리렌더링

// ✅ 분리
const UserContext = React.createContext(null)
const UserAPIContext = React.createContext({ setUser: () => {} })

function UserProvider({ children }) {
  const [user, setUser] = useState(null)

  // setUser는 useCallback으로 참조 고정
  const api = useMemo(() => ({ setUser }), [setUser])

  return (
    <UserAPIContext.Provider value={api}>
      <UserContext.Provider value={user}>
        {children}
      </UserContext.Provider>
    </UserAPIContext.Provider>
  )
}
// user 바뀌어도 setUser만 쓰는 컴포넌트는 리렌더링 안 함

